CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL, password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS datasets (id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL, filename TEXT NOT NULL, rows_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS studies (id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL, dataset_id TEXT NOT NULL REFERENCES datasets(id), features_json TEXT NOT NULL, min_k INTEGER NOT NULL, max_k INTEGER NOT NULL, bootstrap INTEGER NOT NULL, seed INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runs (id TEXT PRIMARY KEY, study_id TEXT NOT NULL REFERENCES studies(id), status TEXT NOT NULL, result_json TEXT, error TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profiles (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), cluster_id INTEGER NOT NULL, name TEXT NOT NULL, notes TEXT NOT NULL, centroid_json TEXT NOT NULL, size INTEGER NOT NULL, UNIQUE(run_id,cluster_id));
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), title TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, archived_by TEXT);
CREATE TABLE IF NOT EXISTS audits (id TEXT PRIMARY KEY, actor TEXT NOT NULL, method TEXT NOT NULL, path TEXT NOT NULL, status INTEGER NOT NULL, created_at TEXT NOT NULL);
